module mac_pipeline (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        in_valid,
    input  logic [15:0] a,
    input  logic [15:0] b,
    input  logic [31:0] c,
    output logic        out_valid,
    output logic [31:0] result
);

    // Stage 1 registers
    logic [31:0] stage1_mult;
    logic [31:0] stage1_c;
    logic        stage1_valid;

    // Stage 2 registers
    logic [31:0] stage2_result;
    logic        stage2_valid;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            stage1_mult  <= 32'd0;
            stage1_c     <= 32'd0;
            stage1_valid <= 1'b0;
            stage2_result <= 32'd0;
            stage2_valid <= 1'b0;
        end else begin
            // Stage 1 execute
            if (in_valid) begin
                stage1_mult <= a * b;
                stage1_c    <= c;
            end
            stage1_valid <= in_valid;

            // Stage 2 execute
            if (stage1_valid) begin
                stage2_result <= stage1_mult + stage1_c;
            end
            stage2_valid  <= stage1_valid;
        end
    end

    assign result    = stage2_result;
    assign out_valid = stage2_valid;

endmodule
